-- Official NBTE polytechnic directory import.
-- Source: National Board for Technical Education, Directory of Accredited Programmes, 25th Edition, June 2025.
-- Extracted from the published PDF list: "List of Polytechnics in Nigeria with Years of Establishment & Ownership".

ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  location = EXCLUDED.location,
  institution_type = EXCLUDED.institution_type,
  ownership = EXCLUDED.ownership,
  state = EXCLUDED.state,
  region = EXCLUDED.region,
  accent_color = EXCLUDED.accent_color,
  community_prompt = EXCLUDED.community_prompt,
  campus_motto = EXCLUDED.campus_motto,
  source_label = EXCLUDED.source_label,
  updated_at = now()
WHERE public.universities.source_label IS NULL OR public.universities.source_label NOT LIKE 'NUC%';
